const https = require('https');
const http  = require('http');

const FAL_KEY  = "443a6432-3b5b-4abe-a925-a6336817f13f:70f93e62dbc7def11558314850ea375c";
const MONTAGEM_HOST = 'montagem';
const MONTAGEM_PORT = 3000;
const REF_IMGS = [
  "https://v3b.fal.media/files/b/0a9d190b/eJgcWqX9t4DJ2Ypx_1InI_IMG_3628.JPG",
  "https://v3b.fal.media/files/b/0a9d190d/MPANCIXNZroF4MEj3lQhq_IMG_3629.JPG",
