const outroText = body.outro_prompt;

const sleep = ms => new Promise(r => setTimeout(r, ms));

function httpsReq(method, hostname, path, hdrs, payload) {
  return new Promise((resolve, reject) => {
    const data = payload ? JSON.stringify(payload) : null;
    const opts = {
      hostname, path, method,
      headers: { ...hdrs, ...(data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {}) }
    };
    const req = https.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); } });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

function httpPost(host, port, path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const opts = {
      hostname: host, port, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
    };
    const req = http.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); } });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

const AUTH = { 'Authorization': `Key ${FAL_KEY}` };

async function submitFal(prompt) {
  const r = await httpsReq('POST', 'queue.fal.run', '/fal-ai/veo3.1/reference-to-video', AUTH, {
    prompt, image_urls: REF_IMGS, aspect_ratio: '9:16', generate_audio: true, resolution: '720p'
  });
  if (!r.request_id) throw new Error('fal submit failed: ' + JSON.stringify(r));
  return r.request_id;
}

async function pollFal(requestId) {
  for (let i = 0; i < 40; i++) {
    await sleep(15000);
    const s = await httpsReq('GET', 'queue.fal.run', `/fal-ai/veo3.1/requests/${requestId}/status`, AUTH, null);
    console.log(`[${pid}] poll ${i+1}: ${s.status}`);
    if (s.status === 'COMPLETED') {
      const res = await httpsReq('GET', 'queue.fal.run', `/fal-ai/veo3.1/requests/${requestId}`, AUTH, null);
      console.log(`[${pid}] result keys: ${Object.keys(res).join(', ')}`);
      // fal may return video in different fields
      const videoUrl = res.video?.url || res.videos?.[0]?.url || res.output?.video?.url || res.output?.url;
      if (!videoUrl) throw new Error('fal completed but no video URL. Keys: ' + Object.keys(res).join(', ') + ' | sample: ' + JSON.stringify(res).slice(0, 300));
      return videoUrl;
    }
    if (s.status === 'FAILED') throw new Error('fal job failed: ' + JSON.stringify(s));
  }
  throw new Error('fal polling timeout after 10min');
}

async function uploadToMinio(falUrl, bucket, key) {
  const r = await httpPost(MONTAGEM_HOST, MONTAGEM_PORT, '/upload-from-url', { url: falUrl, bucket, key });
  if (r.error) throw new Error('upload failed: ' + r.error);
  return r;
}

// --- Intro ---
console.log(`[${pid}] Submitting INTRO...`);
const introId = await submitFal(introText);
console.log(`[${pid}] INTRO request_id: ${introId}`);
const introFalUrl = await pollFal(introId);
console.log(`[${pid}] INTRO url: ${introFalUrl}`);
const introResult = await uploadToMinio(introFalUrl, 'cirlene-video', `${pid}/intro.mp4`);

